            q = [(r,c)]
            while q:
                cr, cc = q.pop(0)
                if (cr,cc) in visited:
                    continue
                visited.add((cr,cc))
                obj.append((cr,cc,val))
                # Check neighbors
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < 4 and 0 <= nc < 18:
                        if grid[nr][nc] == val and (nr,nc) not in visited:
