    [6, 9, 6, 6, 6, 6, 6, 6, 6, 6, 6, 4, 6, 6, 6, 6, 6, 6]
]

from collections import Counter
output_clear = [[6]*18 for _ in range(4)]
for c in range(18):
    vals = []
    non_bg_positions = []
    for r in range(4):
        val = grid[r][c]
        if val != 6:
            vals.append(val)
            non_bg_positions.append((r, val))

    freq = Counter(vals)
    has_repeat = any(count >= 2 for count in freq.values())

    if not has_repeat and vals:
        # Keep non-6 values in same positions
        for r in range(4):
            for cr in non_bg_positions:
                if cr[0] == r:
                    output_clear[r][c] = cr[1]

print("=== Clear cols with repeat>=2, keep unique ===")
